import { StyleSheet } from 'react-native';

const styles = StyleSheet.create({
    containerButton: {
        alignItems: 'center'
    },

    button: {
        backgroundColor: '#333',
        paddingHorizontal: 50,
        borderRadius: 10
    },

    textPrice: {
        color: '#fff',
        fontSize: 20
    },

    valuePrice: {
        color: '#fff',
        fontSize: 18
    },
});
export { styles };
